//! Independently loaded cache definitions; no synthetic positive metadata.
use gielinor_cache::{game::{Definitions,GameCache},symbols};
use gielinor_server::content::light_sources;
use std::{collections::BTreeMap,path::Path};
fn copy(d:&Definitions)->Definitions{Definitions{inventories:BTreeMap::new(),locations:BTreeMap::new(),npcs:BTreeMap::new(),items:d.items.clone(),varbits:BTreeMap::new(),varps:BTreeMap::new(),stats:d.stats.clone()}}
#[test]fn actual_nineteen_items_nine_profiles_and_fail_closed_metadata(){
let dir=std::env::var("PG_SYMBOLS").unwrap();let objects=symbols::load(&[Path::new(&dir)],"obj",None).unwrap();let stat=symbols::load(&[Path::new(&dir)],"stat",None).unwrap();let path=std::env::var("PG_GAME_CACHE").unwrap();let mut cache=GameCache::open(Path::new(&path),0xff_ffff).unwrap();let items=cache.files(2,10,None).unwrap().unwrap();let stats=cache.files(2,200,None).unwrap().unwrap();
let ids=[("tinderbox",590),("unlit_candle",36),("lit_candle",33),("unlit_black_candle",38),("lit_black_candle",32),("torch_unlit",596),("torch_lit",594),("candle_lantern_unlit",4529),("candle_lantern_lit",4531),("candle_lantern_black_unlit",4532),("candle_lantern_black_lit",4534),("oil_lamp_unlit",4522),("oil_lamp_lit",4524),("oil_lantern_unlit",4537),("oil_lantern_lit",4539),("bullseye_lantern_unlit",4548),("bullseye_lantern_lit",4550),("cave_goblin_mining_helmet_unlit",5014),("cave_goblin_mining_helmet_lit",5013)];
let mut defs=Definitions{inventories:BTreeMap::new(),locations:BTreeMap::new(),npcs:BTreeMap::new(),items:BTreeMap::new(),varbits:BTreeMap::new(),varps:BTreeMap::new(),stats:BTreeMap::new()};for(_,id)in ids{defs.items.insert(id as u32,gielinor_cache::definitions::ItemType::decode(&items[&(id as u32)]).unwrap());}defs.stats.insert(11,gielinor_cache::definitions::StatType::decode(&stats[&11]).unwrap());
let expected=[(36,33,1,0,2),(38,32,1,0,2),(596,594,1,3,6),(4529,4531,4,1,3),(4532,4534,4,1,3),(4522,4524,12,1,3),(4537,4539,26,1,3),(4548,4550,49,1,3),(5014,5013,65,2,4)];let rows=light_sources(&objects,&stat,&defs).unwrap();assert_eq!(rows.len(),9);for(r,(raw,lit,level,op,button))in rows.iter().zip(expected){assert_eq!((r.light.skill,r.light.exchange.tool,r.light.exchange.input,r.light.exchange.output,r.light.level,r.light.xp_tenths,r.light.output_count,r.light.ticks),(11,590,raw,lit,level,0,1,0));assert!(r.light.failure.is_none());assert!(r.light.exchange.animation.is_none());assert!(r.light.exchange.members);assert_eq!(defs.items[&(lit as u32)].inventory_ops[op].as_deref(),Some("Extinguish"));assert_eq!((r.extinguish.output,r.extinguish.members,r.extinguish.button_operation,r.extinguish.message),(raw,true,button,Some("You extinguish the light source.")));}
let mut refused=0;for(symbol,id)in ids{for case in 0..10{let mut d=copy(&defs);let mut o=objects.clone();match case{0=>{d.items.remove(&(id as u32));},1=>d.items.get_mut(&(id as u32)).unwrap().name="Wrong".into(),2=>{let v=d.items.get_mut(&(id as u32)).unwrap();v.members=!v.members;},3=>{let v=d.items.get_mut(&(id as u32)).unwrap();v.stackable=!v.stackable;},4=>d.items.get_mut(&(id as u32)).unwrap().dummy=1,5=>d.items.get_mut(&(id as u32)).unwrap().cert.template=799,6=>d.items.get_mut(&(id as u32)).unwrap().placeholder.template=14401,7=>d.items.get_mut(&(id as u32)).unwrap().transform.template=1,8=>{o.insert(symbol.into(),id+100000);},_=>{o.remove(symbol);}}assert!(light_sources(&o,&stat,&d).is_err(),"{symbol} case{case}");refused+=1;}}
for(_,lit,_,op,_)in expected{for label in[None,Some("Wear".into())]{let mut d=copy(&defs);d.items.get_mut(&(lit as u32)).unwrap().inventory_ops[op]=label;assert!(light_sources(&objects,&stat,&d).is_err());refused+=1;}}
for case in 0..7{let mut d=copy(&defs);let mut s=stat.clone();match case{0=>{s.remove("firemaking");},1=>{s.insert("firemaking".into(),12);},2=>{d.stats.remove(&11);},3=>d.stats.get_mut(&11).unwrap().name="Crafting".into(),4=>d.stats.get_mut(&11).unwrap().unreleased=true,5=>d.stats.get_mut(&11).unwrap().min_level=0,_=>d.stats.get_mut(&11).unwrap().max_level=98}assert!(light_sources(&objects,&s,&d).is_err());refused+=1;}assert_eq!(refused,215);
// Current generalized tool field must preserve every prior Crafting factory and resolver.
let mut all=copy(&defs);for (&id,data)in &items{all.items.insert(id,gielinor_cache::definitions::ItemType::decode(data).unwrap());}all.stats.insert(12,gielinor_cache::definitions::StatType::decode(&stats[&12]).unwrap());let seq=symbols::load(&[Path::new(&dir)],"seq",None).unwrap();
use gielinor_server::content as content;let groups=vec![content::gem_cutting(&objects,&seq,&stat,&all).unwrap(),content::snelm_carving(&objects,&seq,&stat,&all).unwrap(),content::glassblowing(&objects,&seq,&stat,&all).unwrap(),content::fallible_gems(&objects,&seq,&stat,&all).unwrap(),content::immediate_tool_crafting(&objects,&seq,&stat,&all).unwrap(),content::crab_carving(&objects,&seq,&stat,&all).unwrap(),content::amethyst_cutting(&objects,&seq,&stat,&all).unwrap(),vec![content::sinew_crafting(&objects,&seq,&stat,&all).unwrap()],vec![content::crafting_finishes(&objects,&stat,&all).unwrap().serpentine_helm]];
assert_eq!(groups.iter().map(|g|g.len()).collect::<Vec<_>>(),vec![7,9,8,3,2,4,4,1,1]);let mut controls=0;
for recipe in groups.into_iter().flatten(){assert_eq!(recipe.skill,12);let mut inv=gielinor_world::inventory::Inventory::new(28,gielinor_world::inventory::StackType::Normal,false);for slot in 0..28{inv.restore_slot(slot,Some(gielinor_world::inventory::Item{id:1931,count:1,vars:0})).unwrap();}for(slot,id)in[(0,recipe.exchange.tool),(1,recipe.exchange.tool),(17,recipe.exchange.input),(26,recipe.exchange.input)]{inv.restore_slot(slot,Some(gielinor_world::inventory::Item{id,count:1,vars:0})).unwrap();}let mut cat=gielinor_world::inventory::Catalog::default();for(&id,d)in &all.items{if d.stackable{cat.stackable.insert(id as i32);}}let mut stats=gielinor_world::stats::Stats::default();stats.set_base(12,99);stats.set_current(12,99);stats.set_current(11,0);stats.set_fine_xp(12,130344311).unwrap();struct Success;impl gielinor_world::npc::RandomSource for Success{fn below(&mut self,n:u32)->u32{assert!(n>0);0}}let job=gielinor_world::tool_crafting::Job{recipe,tool_slot:0,input_slot:17};let(p,success)=job.resolve(&inv,&cat,&stats,125,true,&mut Success).unwrap();assert!(success);let mut expected=inv.clone();expected.restore_slot(17,Some(gielinor_world::inventory::Item{id:recipe.exchange.output,count:recipe.output_count as i32,vars:0})).unwrap();assert_eq!(p.inventory,expected);let mut expected=stats.clone();expected.set_fine_xp(12,130344311+recipe.xp_tenths as i32*125/100).unwrap();assert_eq!(p.stats,expected);controls+=1;}assert_eq!(controls,39);println!("PG_LIGHT_LEGACY_FACTORIES profiles=39 crafting12/firemaking0/full28/retained tools/selected output/per-step125XP");println!("PG_LIGHT_BINDINGS actual_items=19 profiles=9 refused=215");}
